options.afterRender:
function updateSolarDashboard(actualReading) {
  const customDate = new Date();

  // 1. Force calculation specifically to Malaysia Time Zone (UTC+8)
  let hour = customDate.getHours();
  let minute = customDate.getMinutes();

  const timeAsDecimal = hour + minute / 60;

  // 2. Map maximum clear sky bounds for inference calculation 
  let period = "Night";
  let clearSkyMax = 0;

  if (timeAsDecimal >= 6.5 && timeAsDecimal < 7.5) {
    period = "Dawn";
    clearSkyMax = 50;
  } else if (timeAsDecimal >= 7.5 && timeAsDecimal < 11.5) {
    period = "Morning";
    clearSkyMax = 650;
  } else if (timeAsDecimal >= 11.5 && timeAsDecimal < 14.5) {
    period = "Midday Peak";
    clearSkyMax = 900;
  } else if (timeAsDecimal >= 14.5 && timeAsDecimal < 18.5) {
    period = "Afternoon";
    clearSkyMax = 700;
  } else if (timeAsDecimal >= 18.5 && timeAsDecimal < 19.5) {
    period = "Sunset";
    clearSkyMax = 80;
  }

  // 3. Process UI output rendering updates
  const timeStr = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')} MYT`;
  document.getElementById("live-time-display").innerText = timeStr;
  document.getElementById("ui-actual-reading").innerText = `${Math.round(actualReading)} W/m²`;
  document.getElementById("ui-time-period").innerText = period;

  const badge = document.getElementById("ui-weather-badge");
  const penetrationText = document.getElementById("ui-penetration-ratio");

  // Reset any prior badge color classes
  badge.className = "weather-badge";

  if (period === "Night") {
    badge.innerText = "Night Time";
    badge.classList.add("w-night");
    penetrationText.innerText = "Sun is down (Reading is baseline 0)";
    return;
  }

  // Calculate light filtration levels
  const validReading = Math.max(0, actualReading);
  const ratio = Math.min(1.0, validReading / clearSkyMax);
  const percentage = (ratio * 100).toFixed(0);
  penetrationText.innerText = `Sunlight penetration: ${percentage}% of expected max`;

  // 4. Classify weather state visually via CSS tags
  if (ratio >= 0.80) {
    badge.innerText = "☀️ Sunny / Clear";
    badge.classList.add("w-sunny");
  } else if (ratio >= 0.40 && ratio < 0.80) {
    badge.innerText = "⛅ Partly Cloudy";
    badge.classList.add("w-partly_cloudy");
  } else if (ratio >= 0.12 && ratio < 0.40) {
    badge.innerText = "☁️ Overcast / Rainy";
    badge.classList.add("w-overcast");
  } else {
    badge.innerText = "⛈️ Storm / Heavy Fog";
    badge.classList.add("w-storm");
  }
}

updateSolarDashboard(context.data.radiation);

