custom.customCode:
const now = new Date();

const timeAsDecimal = now.getHours() + now.getMinutes() / 60;

let period = 'night';
const actualReading = Number('$radiation');
let clearSkyMax = 0;

if (timeAsDecimal >= 6.5 && timeAsDecimal < 7.5) {
  period = "dawn";
  clearSkyMax = 50;
} else if (timeAsDecimal >= 7.5 && timeAsDecimal < 11.5) {
  period = "morning";
  clearSkyMax = 650;
} else if (timeAsDecimal >= 11.5 && timeAsDecimal < 14.5) { // 11:30 AM to 2:30 PM
  period = "peak";
  clearSkyMax = 900;
} else if (timeAsDecimal >= 14.5 && timeAsDecimal < 18.5) { // 2:30 PM to 6:30 PM
  period = "afternoon";
  clearSkyMax = 700;
} else if (timeAsDecimal >= 18.5 && timeAsDecimal < 19.5) { // 6:30 PM to 7:30 PM
  period = "sunset";
  clearSkyMax = 80;
}

const validReading = Math.max(0, actualReading);
const ratio = Math.min(1.0, validReading / clearSkyMax);

let inferredWeather = "";
if (ratio >= 0.80) {
  inferredWeather = "sunny";          // 80% to 100% of maximum clear sky light
} else if (ratio >= 0.40 && ratio < 0.80) {
  inferredWeather = "partly_cloudy";  // 40% to 79% light (moderate cloud interference)
} else if (ratio >= 0.12 && ratio < 0.40) {
  inferredWeather = "overcast";       // 12% to 39% light (thick cloud layers or light rain)
} else {
  inferredWeather = "storm";          // Below 12% light during daytime (very heavy storm or dark fog)
}

const result = {
  ...frame,
  fields: frame.fields.map((field) => ({
    ...field,
    values: [period === 'night' ? 'night' : inferredWeather]
  }))
}

return Promise.resolve(result);
